files.schemas/v0.2/MeasurementContext.json:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://openworkplacehealth.org/schemas/v0.2/MeasurementContext.json",
  "title": "OWHS MeasurementContext v0.2",
  "description": "What makes scores comparable: the producing system, the scoring descriptor and its provenance, the data window it describes, and the stated limitations. Immutable: a changed descriptor is a new context.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "contextId",
    "orgId",
    "producingSystem",
    "scoringDescriptor",
    "knownLimitations"
  ],
  "properties": {
    "contextId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Primary identifier, unique within the organisation."
    },
    "orgId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Organisation scope."
    },
    "producingSystem": {
      "type": "string",
      "minLength": 1,
      "maxLength": 2000,
      "description": "System and version that produced the scores. Identifies, does not disclose architecture."
    },
    "knownLimitations": {
      "type": "string",
      "minLength": 1,
      "maxLength": 2000,
      "description": "Stated limitations. 'Not assessed' means exactly that."
    },
    "recallPeriod": {
      "type": "string",
      "minLength": 1,
      "maxLength": 2000,
      "description": "The instrument's recall period where its source specifies one, for example 'preceding two weeks'. Distinct from observationWindow."
    },
    "scoringDescriptor": {
      "type": "object",
      "properties": {
        "descriptorId": {
          "type": "string",
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
          "description": "Identifier of this descriptor."
        },
        "descriptorVersion": {
          "type": "string",
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
          "description": "Version of this descriptor."
        },
        "method": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000,
          "description": "Scoring method, in the producer's words."
        },
        "estimand": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000,
          "description": "What the score estimates: a period mean, a modelled current state, a rolling average with its window, and so on."
        },
        "observationWindow": {
          "type": "object",
          "properties": {
            "start": {
              "type": "string",
              "format": "date-time",
              "pattern": "(Z|[+-]\\d{2}:\\d{2})$"
            },
            "end": {
              "type": "string",
              "format": "date-time",
              "pattern": "(Z|[+-]\\d{2}:\\d{2})$"
            }
          },
          "required": [
            "start",
            "end"
          ],
          "additionalProperties": false,
          "description": "The data the descriptor represents. Not the instrument's recall period."
        },
        "sourceRef": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000,
          "description": "Where the method is published or held."
        },
        "scoreUnit": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000,
          "description": "Unit of the score."
        },
        "higherScoreMeaning": {
          "type": "string",
          "enum": [
            "higher-construct",
            "lower-construct",
            "not-ordered"
          ]
        },
        "nativeScale": {
          "type": "object",
          "properties": {
            "min": {
              "type": "number"
            },
            "max": {
              "type": "number"
            }
          },
          "required": [
            "min",
            "max"
          ],
          "additionalProperties": false,
          "description": "Bounds of the native response scale."
        },
        "normalisation": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
              "description": "Identifier of the rule or table."
            },
            "version": {
              "type": "string",
              "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
              "description": "Version of the rule or table."
            },
            "sourceRef": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2000,
              "description": "Where the rule or table is published or held."
            },
            "description": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2000,
              "description": "Optional description."
            }
          },
          "required": [
            "id",
            "version",
            "sourceRef"
          ],
          "additionalProperties": false,
          "description": "Rule that maps nativeValue to 0..100. Required by any observation carrying normalisedValue."
        },
        "banding": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
              "description": "Identifier of the rule or table."
            },
            "version": {
              "type": "string",
              "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
              "description": "Version of the rule or table."
            },
            "sourceRef": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2000,
              "description": "Where the rule or table is published or held."
            },
            "description": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2000,
              "description": "Optional description."
            }
          },
          "required": [
            "id",
            "version",
            "sourceRef"
          ],
          "additionalProperties": false,
          "description": "Banding table. Required by any administration carrying band."
        },
        "threshold": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
              "description": "Identifier of the rule or table."
            },
            "version": {
              "type": "string",
              "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
              "description": "Version of the rule or table."
            },
            "sourceRef": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2000,
              "description": "Where the rule or table is published or held."
            },
            "description": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2000,
              "description": "Optional description."
            }
          },
          "required": [
            "id",
            "version",
            "sourceRef"
          ],
          "additionalProperties": false,
          "description": "Threshold rule. Required by any administration carrying aboveThresholdFlag."
        },
        "missingResponseRule": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
              "description": "Identifier of the rule or table."
            },
            "version": {
              "type": "string",
              "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
              "description": "Version of the rule or table."
            },
            "sourceRef": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2000,
              "description": "Where the rule or table is published or held."
            },
            "description": {
              "type": "string",
              "minLength": 1,
              "maxLength": 2000,
              "description": "Optional description."
            }
          },
          "required": [
            "id",
            "version",
            "sourceRef"
          ],
          "additionalProperties": false,
          "description": "Scoring rule for partial administrations. Required by any partial administration carrying scores."
        }
      },
      "required": [
        "descriptorId",
        "descriptorVersion",
        "method",
        "estimand",
        "observationWindow",
        "sourceRef"
      ],
      "additionalProperties": false,
      "description": "Closed object with open method identifiers: the fields are fixed, the methods they name are the producer's."
    },
    "ext": {
      "type": "object",
      "$comment": "Extension namespaces and values are structurally checked. The named identifier keys are prohibited recursively; OHEpisode also prohibits its named clinical-content keys recursively. This is not detection of identifiers or clinical meaning hidden in allowed keys or values. All extensions remain subject to P1-P5 and their applicable profile. A core-only pass does not establish profile or Level 3 conformance.",
      "propertyNames": {
        "pattern": "^owhs-[a-z][a-z0-9]*(?:-[a-z0-9]+)*$",
        "maxLength": 64
      },
      "additionalProperties": {
        "$ref": "#/$defs/owhsExtensionObject"
      }
    }
  },
  "$defs": {
    "owhsExtensionObject": {
      "type": "object",
      "propertyNames": {
        "not": {
          "enum": [
            "name",
            "nino",
            "email",
            "dateOfBirth",
            "address"
          ]
        }
      },
      "additionalProperties": {
        "$ref": "#/$defs/owhsExtensionValue"
      }
    },
    "owhsExtensionValue": {
      "anyOf": [
        {
          "type": [
            "string",
            "number",
            "boolean",
            "null"
          ]
        },
        {
          "type": "array",
          "items": {
            "$ref": "#/$defs/owhsExtensionValue"
          }
        },
        {
          "$ref": "#/$defs/owhsExtensionObject"
        }
      ]
    }
  }
}

files.schemas/v0.2/WellbeingObservation.json:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://openworkplacehealth.org/schemas/v0.2/WellbeingObservation.json",
  "title": "OWHS WellbeingObservation v0.2",
  "description": "One answer to one survey item on one occasion, any vendor. Individual-never at this grain: it leaves an organisation only through an AggregateReport.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "observationId",
    "orgId",
    "pseudonymId",
    "contextId",
    "itemId",
    "itemVersion",
    "constructCode",
    "nativeValue",
    "occasionTs",
    "safeguardingCategory"
  ],
  "properties": {
    "observationId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Primary identifier, unique within the organisation."
    },
    "orgId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Organisation scope. Metadata remains subject to P1."
    },
    "pseudonymId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "WorkerPseudonym reference. The same string in two organisations is not the same person."
    },
    "contextId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Same-organisation MeasurementContext reference; one immutable scoring and interpretation descriptor."
    },
    "itemId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Item identifier. No item wording is carried."
    },
    "itemVersion": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Version of this item and its response options."
    },
    "constructCode": {
      "type": "string",
      "enum": [
        "demands",
        "control",
        "support",
        "relationships",
        "role",
        "change",
        "mental-health",
        "physical-health",
        "musculoskeletal",
        "financial-wellbeing",
        "sleep-fatigue"
      ],
      "$comment": "codelist:construct-domain@0.1.0",
      "description": "Construct the item measures."
    },
    "nativeValue": {
      "type": "number",
      "description": "Observed response on the declared native scale."
    },
    "normalisedValue": {
      "type": "number",
      "description": "Arithmetic transformation of nativeValue to 0..100 under the context's declared normalisation. Not equivalence with any other item or score.",
      "minimum": 0,
      "maximum": 100
    },
    "occasionTs": {
      "type": "string",
      "format": "date-time",
      "pattern": "(Z|[+-]\\d{2}:\\d{2})$",
      "description": "Observation occasion, with an asserted time zone."
    },
    "collectionChannel": {
      "type": "string",
      "enum": [
        "email",
        "sms",
        "app",
        "kiosk",
        "paper"
      ],
      "$comment": "codelist:collection-channel@0.1.0",
      "description": "How the answer was collected."
    },
    "safeguardingCategory": {
      "type": "boolean",
      "description": "Explicit flag. Absence is not inferred; the field is required."
    },
    "samplingDesign": {
      "type": "object",
      "properties": {
        "design": {
          "type": "string",
          "enum": [
            "complete",
            "rotating-subset",
            "adaptive"
          ],
          "$comment": "codelist:sampling-design@0.1.0",
          "description": "Sampling design under which this item was offered."
        },
        "scheduleRef": {
          "type": "string",
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
          "description": "Schedule reference, required for rotating-subset and adaptive designs."
        }
      },
      "required": [
        "design"
      ],
      "additionalProperties": false,
      "description": "Metadata only."
    },
    "ext": {
      "type": "object",
      "$comment": "Extension namespaces and values are structurally checked. The named identifier keys are prohibited recursively; OHEpisode also prohibits its named clinical-content keys recursively. This is not detection of identifiers or clinical meaning hidden in allowed keys or values. All extensions remain subject to P1-P5 and their applicable profile. A core-only pass does not establish profile or Level 3 conformance.",
      "propertyNames": {
        "pattern": "^owhs-[a-z][a-z0-9]*(?:-[a-z0-9]+)*$",
        "maxLength": 64
      },
      "additionalProperties": {
        "$ref": "#/$defs/owhsExtensionObject"
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "samplingDesign": {
            "properties": {
              "design": {
                "enum": [
                  "rotating-subset",
                  "adaptive"
                ]
              }
            },
            "required": [
              "design"
            ]
          }
        },
        "required": [
          "samplingDesign"
        ]
      },
      "then": {
        "properties": {
          "samplingDesign": {
            "required": [
              "design",
              "scheduleRef"
            ]
          }
        }
      }
    }
  ],
  "$defs": {
    "owhsExtensionObject": {
      "type": "object",
      "propertyNames": {
        "not": {
          "enum": [
            "name",
            "nino",
            "email",
            "dateOfBirth",
            "address"
          ]
        }
      },
      "additionalProperties": {
        "$ref": "#/$defs/owhsExtensionValue"
      }
    },
    "owhsExtensionValue": {
      "anyOf": [
        {
          "type": [
            "string",
            "number",
            "boolean",
            "null"
          ]
        },
        {
          "type": "array",
          "items": {
            "$ref": "#/$defs/owhsExtensionValue"
          }
        },
        {
          "$ref": "#/$defs/owhsExtensionObject"
        }
      ]
    }
  }
}

files.schemas/v0.2/InstrumentAdministration.js:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://openworkplacehealth.org/schemas/v0.2/InstrumentAdministration.json",
  "title": "OWHS InstrumentAdministration v0.2",
  "description": "One completed, partial or abandoned administration of a validated instrument: scores and bands, never item text. Individual-never at this grain. The schema does not grant a licence to administer the instrument.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "administrationId",
    "orgId",
    "pseudonymId",
    "contextId",
    "instrumentId",
    "instrumentCitation",
    "instrumentVersion",
    "occasionTs",
    "constructCodes",
    "completionStatus"
  ],
  "properties": {
    "administrationId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Primary identifier, unique within the organisation."
    },
    "orgId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Organisation scope."
    },
    "pseudonymId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "WorkerPseudonym reference."
    },
    "contextId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Same-organisation MeasurementContext reference."
    },
    "instrumentId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Stable identifier of the exact instrument or form. Not its registry grade."
    },
    "instrumentCitation": {
      "type": "string",
      "minLength": 1,
      "maxLength": 2000,
      "description": "Bibliographic citation of the instrument. No questionnaire item text."
    },
    "instrumentVersion": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Form or version, separate from any dataset version."
    },
    "occasionTs": {
      "type": "string",
      "format": "date-time",
      "pattern": "(Z|[+-]\\d{2}:\\d{2})$",
      "description": "Administration occasion, with an asserted time zone."
    },
    "constructCodes": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "string",
        "enum": [
          "demands",
          "control",
          "support",
          "relationships",
          "role",
          "change",
          "mental-health",
          "physical-health",
          "musculoskeletal",
          "financial-wellbeing",
          "sleep-fatigue"
        ],
        "$comment": "codelist:construct-domain@0.1.0"
      },
      "description": "Constructs the instrument measures; a multidimensional instrument lists several without inventing one total construct."
    },
    "completionStatus": {
      "type": "string",
      "enum": [
        "complete",
        "partial",
        "abandoned"
      ],
      "$comment": "codelist:completion-status@0.1.0",
      "description": "complete, partial or abandoned."
    },
    "totalScore": {
      "type": "number",
      "description": "Total score, where the instrument defines one."
    },
    "subscaleScores": {
      "type": "object",
      "minProperties": 1,
      "propertyNames": {
        "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
        "not": {
          "enum": [
            "name",
            "nino",
            "email",
            "dateOfBirth",
            "address"
          ]
        }
      },
      "additionalProperties": {
        "type": "number"
      },
      "description": "Subscale identifier to finite score."
    },
    "band": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Band label under the context's declared banding."
    },
    "aboveThresholdFlag": {
      "type": "boolean",
      "description": "Under the context's declared threshold. Severe-distress measures carry the n>=10 floor at aggregation (P2)."
    },
    "ext": {
      "type": "object",
      "$comment": "Extension namespaces and values are structurally checked. The named identifier keys are prohibited recursively; OHEpisode also prohibits its named clinical-content keys recursively. This is not detection of identifiers or clinical meaning hidden in allowed keys or values. All extensions remain subject to P1-P5 and their applicable profile. A core-only pass does not establish profile or Level 3 conformance.",
      "propertyNames": {
        "pattern": "^owhs-[a-z][a-z0-9]*(?:-[a-z0-9]+)*$",
        "maxLength": 64
      },
      "additionalProperties": {
        "$ref": "#/$defs/owhsExtensionObject"
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "completionStatus": {
            "const": "complete"
          }
        }
      },
      "then": {
        "anyOf": [
          {
            "required": [
              "totalScore"
            ]
          },
          {
            "required": [
              "subscaleScores"
            ]
          }
        ]
      }
    },
    {
      "if": {
        "properties": {
          "completionStatus": {
            "const": "abandoned"
          }
        }
      },
      "then": {
        "not": {
          "anyOf": [
            {
              "required": [
                "totalScore"
              ]
            },
            {
              "required": [
                "subscaleScores"
              ]
            },
            {
              "required": [
                "band"
              ]
            },
            {
              "required": [
                "aboveThresholdFlag"
              ]
            }
          ]
        }
      }
    }
  ],
  "$defs": {
    "owhsExtensionObject": {
      "type": "object",
      "propertyNames": {
        "not": {
          "enum": [
            "name",
            "nino",
            "email",
            "dateOfBirth",
            "address"
          ]
        }
      },
      "additionalProperties": {
        "$ref": "#/$defs/owhsExtensionValue"
      }
    },
    "owhsExtensionValue": {
      "anyOf": [
        {
          "type": [
            "string",
            "number",
            "boolean",
            "null"
          ]
        },
        {
          "type": "array",
          "items": {
            "$ref": "#/$defs/owhsExtensionValue"
          }
        },
        {
          "$ref": "#/$defs/owhsExtensionObject"
        }
      ]
    }
  }
}

files.schemas/v0.2/AggregateReport.json:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://openworkplacehealth.org/schemas/v0.2/AggregateReport.json",
  "title": "OWHS AggregateReport v0.2",
  "description": "Employer-visible aggregate results and their suppression declarations. Structural consistency of declarations, not a disclosure assessment: the schema cannot know the recipient, and a safeguarding record valid as suppressed must still never enter employer output (P4).",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "reportId",
    "orgId",
    "level",
    "periodStart",
    "periodEnd",
    "n",
    "headcount",
    "eligibleN",
    "completionRate",
    "metricCode",
    "measureKind",
    "releaseCategory",
    "suppressed",
    "contextId"
  ],
  "properties": {
    "reportId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Primary identifier, unique within the organisation."
    },
    "orgId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Organisation scope."
    },
    "level": {
      "type": "string",
      "enum": [
        "org",
        "unit"
      ]
    },
    "unitId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "OrgUnit reference; required at unit level, forbidden at org level."
    },
    "periodStart": {
      "type": "string",
      "format": "date"
    },
    "periodEnd": {
      "type": "string",
      "format": "date",
      "description": "Inclusive period, ordered."
    },
    "n": {
      "type": "integer",
      "minimum": 0,
      "description": "Distinct people contributing to this metric's estimate in this window."
    },
    "observationCount": {
      "type": "integer",
      "minimum": 0,
      "description": "Responses underlying the estimate; may exceed n with repeated observations."
    },
    "headcount": {
      "type": "integer",
      "minimum": 0,
      "description": "In-scope distinct roster for the declared window."
    },
    "eligibleN": {
      "type": "integer",
      "minimum": 0,
      "description": "Distinct people eligible or offered this metric in the window."
    },
    "completionRate": {
      "type": [
        "number",
        "null"
      ],
      "minimum": 0,
      "maximum": 1,
      "description": "n divided by eligibleN; null only when eligibleN is 0."
    },
    "metricCode": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Metric identifier. Not presumed equal to a construct code."
    },
    "measureKind": {
      "type": "string",
      "enum": [
        "observation",
        "instrument",
        "other"
      ],
      "description": "Source grain, not a reliability claim."
    },
    "releaseCategory": {
      "type": "string",
      "enum": [
        "ordinary",
        "severe-distress",
        "safeguarding"
      ],
      "description": "Producer-declared. Misclassification is not detected by a numerical gate."
    },
    "value": {
      "type": "number",
      "description": "The estimate. Present only when not suppressed."
    },
    "interval": {
      "type": "object",
      "properties": {
        "low": {
          "type": "number"
        },
        "high": {
          "type": "number"
        },
        "level": {
          "type": "number",
          "exclusiveMinimum": 0,
          "exclusiveMaximum": 1
        },
        "method": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000,
          "description": "Interval method."
        },
        "sourceRef": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000,
          "description": "Where the method is published."
        }
      },
      "required": [
        "low",
        "high",
        "level",
        "method"
      ],
      "additionalProperties": false
    },
    "suppressed": {
      "type": "boolean"
    },
    "suppressionReason": {
      "type": "string",
      "enum": [
        "below-floor",
        "safeguarding",
        "low-completion"
      ],
      "$comment": "codelist:suppression-reason@0.1.0",
      "description": "Required when suppressed; forbidden otherwise."
    },
    "contextId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "description": "Same-organisation MeasurementContext reference."
    },
    "benchmarkRef": {
      "type": "object",
      "properties": {
        "benchmarkId": {
          "type": "string",
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
          "description": "BenchmarkRelease identifier."
        },
        "releaseVersion": {
          "type": "string",
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
          "description": "Immutable release version."
        },
        "sourceRef": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000,
          "description": "Where the release is published."
        }
      },
      "required": [
        "benchmarkId",
        "releaseVersion",
        "sourceRef"
      ],
      "additionalProperties": false,
      "description": "Reference to a comparison release. No implied score equivalence. Not resolved by the core validator."
    },
    "ext": {
      "type": "object",
      "$comment": "Extension namespaces and values are structurally checked. The named identifier keys are prohibited recursively; OHEpisode also prohibits its named clinical-content keys recursively. This is not detection of identifiers or clinical meaning hidden in allowed keys or values. All extensions remain subject to P1-P5 and their applicable profile. A core-only pass does not establish profile or Level 3 conformance.",
      "propertyNames": {
        "pattern": "^owhs-[a-z][a-z0-9]*(?:-[a-z0-9]+)*$",
        "maxLength": 64
      },
      "additionalProperties": {
        "$ref": "#/$defs/owhsExtensionObject"
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "level": {
            "const": "unit"
          }
        }
      },
      "then": {
        "required": [
          "unitId"
        ]
      },
      "else": {
        "not": {
          "required": [
            "unitId"
          ]
        }
      }
    },
    {
      "if": {
        "properties": {
          "suppressed": {
            "const": true
          }
        }
      },
      "then": {
        "required": [
          "suppressionReason"
        ],
        "not": {
          "anyOf": [
            {
              "required": [
                "value"
              ]
            },
            {
              "required": [
                "interval"
              ]
            }
          ]
        }
      },
      "else": {
        "required": [
          "value"
        ],
        "not": {
          "required": [
            "suppressionReason"
          ]
        }
      }
    },
    {
      "if": {
        "properties": {
          "n": {
            "maximum": 4
          }
        }
      },
      "then": {
        "properties": {
          "suppressed": {
            "const": true
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "releaseCategory": {
            "const": "severe-distress"
          },
          "n": {
            "maximum": 9
          }
        },
        "required": [
          "releaseCategory"
        ]
      },
      "then": {
        "properties": {
          "suppressed": {
            "const": true
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "releaseCategory": {
            "const": "safeguarding"
          }
        },
        "required": [
          "releaseCategory"
        ]
      },
      "then": {
        "properties": {
          "suppressed": {
            "const": true
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "eligibleN": {
            "const": 0
          }
        }
      },
      "then": {
        "properties": {
          "completionRate": {
            "type": "null"
          },
          "n": {
            "const": 0
          },
          "suppressed": {
            "const": true
          }
        }
      }
    }
  ],
  "$defs": {
    "owhsExtensionObject": {
      "type": "object",
      "propertyNames": {
        "not": {
          "enum": [
            "name",
            "nino",
            "email",
            "dateOfBirth",
            "address"
          ]
        }
      },
      "additionalProperties": {
        "$ref": "#/$defs/owhsExtensionValue"
      }
    },
    "owhsExtensionValue": {
      "anyOf": [
        {
          "type": [
            "string",
            "number",
            "boolean",
            "null"
          ]
        },
        {
          "type": "array",
          "items": {
            "$ref": "#/$defs/owhsExtensionValue"
          }
        },
        {
          "$ref": "#/$defs/owhsExtensionObject"
        }
      ]
    }
  }
}

files.schemas/v0.2/BenchmarkRelease.json:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://openworkplacehealth.org/schemas/v0.2/BenchmarkRelease.json",
  "title": "OWHS BenchmarkRelease v0.2",
  "description": "One versioned comparison distribution for one declared metric, scoring rule, population and data period. Sample composition and exclusion are declarations, not verified truth. Percentiles do not establish representativeness, clinical thresholds, anonymity or comparability with a different measure.",
  "type": "object",
  "properties": {
    "benchmarkId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "not": {
        "pattern": "\\s"
      }
    },
    "releaseVersion": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "not": {
        "pattern": "\\s"
      }
    },
    "composition": {
      "type": "object",
      "properties": {
        "orgCount": {
          "type": "integer",
          "minimum": 1
        },
        "sectors": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^[0-9]{5}$",
            "minLength": 5,
            "maxLength": 5,
            "$comment": "UK SIC 2007 subclass syntax only. Membership, currentness and Companies House filing eligibility are not checked."
          },
          "minItems": 0,
          "uniqueItems": true
        },
        "sicVersion": {
          "type": "string",
          "const": "2007"
        },
        "sizeBands": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "micro",
              "small",
              "medium",
              "large"
            ],
            "$comment": "codelist:org-size-band@0.1.1"
          },
          "minItems": 0,
          "uniqueItems": true
        },
        "sampleSizes": {
          "type": "object",
          "properties": {
            "people": {
              "type": "integer",
              "minimum": 1
            },
            "observations": {
              "type": "integer",
              "minimum": 0
            }
          },
          "required": [
            "people"
          ],
          "additionalProperties": false
        }
      },
      "required": [
        "orgCount",
        "sectors",
        "sicVersion",
        "sizeBands",
        "sampleSizes"
      ],
      "additionalProperties": false
    },
    "percentiles": {
      "type": "object",
      "properties": {
        "method": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000,
          "description": "Published quantile algorithm, weighting and handling of ties/missing values. No universal quantile algorithm is presumed."
        },
        "values": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "probability": {
                "type": "number",
                "minimum": 0,
                "maximum": 1
              },
              "value": {
                "type": "number"
              }
            },
            "required": [
              "probability",
              "value"
            ],
            "additionalProperties": false
          },
          "minItems": 1
        }
      },
      "required": [
        "method",
        "values"
      ],
      "additionalProperties": false
    },
    "leaveOneOut": {
      "type": "boolean"
    },
    "excludedOrgId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
      "not": {
        "pattern": "\\s"
      }
    },
    "validFrom": {
      "type": "string",
      "format": "date"
    },
    "validTo": {
      "type": "string",
      "format": "date"
    },
    "source": {
      "type": "string",
      "minLength": 1,
      "maxLength": 2000
    },
    "dataPeriodStart": {
      "type": "string",
      "format": "date"
    },
    "dataPeriodEnd": {
      "type": "string",
      "format": "date"
    },
    "measure": {
      "type": "object",
      "properties": {
        "metricCode": {
          "type": "string",
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
          "not": {
            "pattern": "\\s"
          }
        },
        "instrumentId": {
          "type": "string",
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
          "not": {
            "pattern": "\\s"
          }
        },
        "instrumentVersion": {
          "type": "string",
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$",
          "not": {
            "pattern": "\\s"
          }
        },
        "scoreUnit": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000
        },
        "scoringDescriptorRef": {
          "type": "string",
          "minLength": 1,
          "maxLength": 2000
        }
      },
      "required": [
        "metricCode",
        "scoreUnit",
        "scoringDescriptorRef"
      ],
      "additionalProperties": false,
      "dependentRequired": {
        "instrumentId": [
          "instrumentVersion"
        ],
        "instrumentVersion": [
          "instrumentId"
        ]
      }
    },
    "population": {
      "type": "string",
      "minLength": 1,
      "maxLength": 2000
    },
    "samplingMethod": {
      "type": "string",
      "minLength": 1,
      "maxLength": 2000
    },
    "knownLimitations": {
      "type": "string",
      "minLength": 1,
      "maxLength": 2000
    },
    "releaseCategory": {
      "type": "string",
      "enum": [
        "ordinary",
        "severe-distress",
        "safeguarding"
      ],
      "$comment": "codelist:release-category@0.1.0"
    },
    "ext": {
      "type": "object",
      "$comment": "Extension namespaces and values are structurally checked. The named identifier keys are prohibited recursively; OHEpisode also prohibits its named clinical-content keys recursively. This is not detection of identifiers or clinical meaning hidden in allowed keys or values. All extensions remain subject to P1-P5 and their applicable profile. A core-only pass does not establish profile or Level 3 conformance.",
      "propertyNames": {
        "pattern": "^owhs-[a-z][a-z0-9]*(?:-[a-z0-9]+)*$",
        "maxLength": 64
      },
      "additionalProperties": {
        "$ref": "#/$defs/owhsExtensionObject"
      }
    }
  },
  "required": [
    "benchmarkId",
    "releaseVersion",
    "composition",
    "percentiles",
    "leaveOneOut",
    "validFrom",
    "validTo",
    "source",
    "dataPeriodStart",
    "dataPeriodEnd",
    "measure",
    "population",
    "samplingMethod",
    "knownLimitations",
    "releaseCategory"
  ],
  "additionalProperties": false,
  "$defs": {
    "owhsExtensionObject": {
      "type": "object",
      "propertyNames": {
        "not": {
          "enum": [
            "name",
            "nino",
            "email",
            "dateOfBirth",
            "address"
          ]
        }
      },
      "additionalProperties": {
        "$ref": "#/$defs/owhsExtensionValue"
      }
    },
    "owhsExtensionValue": {
      "anyOf": [
        {
          "type": [
            "string",
            "number",
            "boolean",
            "null"
          ]
        },
        {
          "type": "array",
          "items": {
            "$ref": "#/$defs/owhsExtensionValue"
          }
        },
        {
          "$ref": "#/$defs/owhsExtensionObject"
        }
      ]
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "leaveOneOut": {
            "const": true
          }
        },
        "required": [
          "leaveOneOut"
        ]
      },
      "then": {
        "required": [
          "excludedOrgId"
        ]
      },
      "else": {
        "not": {
          "anyOf": [
            {
              "required": [
                "excludedOrgId"
              ]
            }
          ]
        }
      }
    },
    {
      "if": {
        "properties": {
          "releaseCategory": {
            "const": "ordinary"
          }
        },
        "required": [
          "releaseCategory"
        ]
      },
      "then": {
        "properties": {
          "composition": {
            "properties": {
              "sampleSizes": {
                "properties": {
                  "people": {
                    "minimum": 5
                  }
                }
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "releaseCategory": {
            "const": "severe-distress"
          }
        },
        "required": [
          "releaseCategory"
        ]
      },
      "then": {
        "properties": {
          "composition": {
            "properties": {
              "sampleSizes": {
                "properties": {
                  "people": {
                    "minimum": 10
                  }
                }
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "releaseCategory": {
            "const": "safeguarding"
          }
        },
        "required": [
          "releaseCategory"
        ]
      },
      "then": false
    }
  ]
}

